import heapq
from collections import defaultdict

class Twitter:
    def __init__(self):
        self.time = 0
        self.tweets = defaultdict(list)    # user → [(time, tweetId)], oldest first
        self.following = defaultdict(set)

    def postTweet(self, userId, tweetId):
        self.time += 1
        self.tweets[userId].append((self.time, tweetId))

    def getNewsFeed(self, userId):
        heap = []                          # newest tweet of each followee list
        for user in self.following[userId] | {userId}:
            if self.tweets[user]:
                i = len(self.tweets[user]) - 1
                time, tweet = self.tweets[user][i]
                heap.append((-time, tweet, user, i))
        heapq.heapify(heap)
        feed = []
        while heap and len(feed) < 10:
            _, tweet, user, i = heapq.heappop(heap)
            feed.append(tweet)
            if i > 0:                      # advance that user's list
                time, older = self.tweets[user][i - 1]
                heapq.heappush(heap, (-time, older, user, i - 1))
        return feed

    def follow(self, followerId, followeeId):
        if followerId != followeeId:
            self.following[followerId].add(followeeId)

    def unfollow(self, followerId, followeeId):
        self.following[followerId].discard(followeeId)

