import random

class RandomizedSet:
    def __init__(self):
        self.values = []
        self.index = {}                # value → position in values

    def insert(self, val):
        if val in self.index:
            return False
        self.index[val] = len(self.values)
        self.values.append(val)
        return True

    def remove(self, val):
        if val not in self.index:
            return False
        i, last = self.index[val], self.values[-1]
        self.values[i], self.index[last] = last, i   # move last into the hole
        self.values.pop()
        del self.index[val]
        return True

    def getRandom(self):
        return random.choice(self.values)

